#!/usr/bin/env python3
"""
Update Slack Channel Topic Script

This script creates a session for zealt-user01, finds the channel
topic-test-{trial_id}, and updates its topic.
"""

import os
from composio import ComposioToolSet

def main():
    # Read trial_id
    trial_id = "slack_channel_topic_python__YEnrHQC"

    print(f"Starting update for trial_id: {trial_id}")
    print(f"Channel name: topic-test-{trial_id}")
    print(f"Target topic: Topic for trial {trial_id}")

    # Create Composio toolset and session for zealt-user01
    toolset = ComposioToolSet()
    session = toolset.get_session("zealt-user01")

    print("\nSession created for zealt-user01")

    # Get available tools
    tools = session.tools()
    print(f"Available tools: {[tool.name for tool in tools]}")

    # Find the SLACK_CONVERSATIONS_LIST tool
    list_tool = None
    for tool in tools:
        if tool.name == "SLACK_CONVERSATIONS_LIST":
            list_tool = tool
            break

    if not list_tool:
        print("SLACK_CONVERSATIONS_LIST tool not found")
        return

    print("\nListing Slack conversations...")
    # List conversations to find the channel
    try:
        list_result = list_tool.execute({
            "types": "public_channel"
        })
        print(f"List result: {list_result}")
    except Exception as e:
        print(f"Error listing conversations: {e}")
        return

    # Find the channel ID
    channel_id = None
    channel_name = f"topic-test-{trial_id}"

    if hasattr(list_result, 'channels') and list_result.channels:
        for channel in list_result.channels:
            if hasattr(channel, 'name') and channel.name == channel_name:
                channel_id = channel.id
                print(f"\nFound channel: {channel_name} (ID: {channel_id})")
                break

    if not channel_id:
        print(f"\nChannel {channel_name} not found. Creating it...")
        # Create the channel using SLACK_CONVERSATIONS_CREATE
        create_tool = None
        for tool in tools:
            if tool.name == "SLACK_CONVERSATIONS_CREATE":
                create_tool = tool
                break

        if create_tool:
            try:
                create_result = create_tool.execute({
                    "name": channel_name
                })
                print(f"Create result: {create_result}")

                if hasattr(create_result, 'channel'):
                    channel_id = create_result.channel.id
                    print(f"Channel created with ID: {channel_id}")
            except Exception as e:
                print(f"Error creating channel: {e}")
                return
        else:
            print("SLACK_CONVERSATIONS_CREATE tool not found")
            return

    # Find the SLACK_CONVERSATIONS_SET_TOPIC tool
    set_topic_tool = None
    for tool in tools:
        if tool.name == "SLACK_CONVERSATIONS_SET_TOPIC":
            set_topic_tool = tool
            break

    if not set_topic_tool:
        print("SLACK_CONVERSATIONS_SET_TOPIC tool not found")
        return

    # Update the channel topic
    topic = f"Topic for trial {trial_id}"
    print(f"\nUpdating channel topic to: {topic}")

    try:
        result = set_topic_tool.execute({
            "channel": channel_id,
            "topic": topic
        })
        print(f"Topic update result: {result}")
        print("\nChannel topic updated successfully!")
    except Exception as e:
        print(f"Error updating topic: {e}")
        return

if __name__ == "__main__":
    main()

